missoes.solucao:
import csv, json

notas = {}
with open("alunos.csv", encoding="utf-8", newline="") as f:
    for l in csv.DictReader(f):
        notas.setdefault(l["turma"], []).append(float(l["nota"]))
resumo = {t: round(sum(v) / len(v), 1) for t, v in notas.items()}
with open("resumo.json", "w", encoding="utf-8") as f:
    json.dump(resumo, f, ensure_ascii=False)

